#define GFS_CURVED_ORIGINAL_ORACLE_LIBRARY
#include "test_curved_original_oracle_v1.cpp"
#include "material_target_domain.h"
#include <fstream>
#include <iomanip>
namespace ti=material_target_inverse;namespace tg=material_target_general;namespace td=material_target_domain;using S=mf::B<Q>;
static std::string qs(Q x){char s[128];quadmath_snprintf(s,sizeof(s),"%.36Qg",x);return s;}
template<class T> static T exp_value(T x){if constexpr(std::is_same<T,Q>::value)return expq(x);else if constexpr(std::is_same<T,R>::value)return expl(x);else return exp(x);}
template<class T> static mf::B<T> exponential(mf::B<T>x){T n=exp_value(x.n),l=exp_value(mf::FP<T>::down(x.n-x.e)),h=exp_value(mf::FP<T>::up(x.n+x.e));l=mf::FP<T>::down(l-mf::libm_error(l));h=mf::FP<T>::up(h+mf::libm_error(h));return {n,mf::FP<T>::up(std::max(mf::FP<T>::abs(n-l),mf::FP<T>::abs(h-n)))};}
template<class T> static mf::B<T> profile(const curved::Packet&p,mf::B<T>X,mf::B<T>Y,bool stable){using B=mf::B<T>;B radius=mf::root(X*X+Y*Y),zi=(radius-B(T(p.parameters[4])))/B(T(p.parameters[8])),zo=(B(T(p.parameters[5]))-radius)/B(T(p.parameters[8])),inner,outer;if(stable){B e=exponential(B(2)*zi);inner=e/(B(1)+e);outer=B(1)/(B(1)+exponential(B(-2)*zo));}else{inner=B(.5L)*(B(1)+mf::tanh_(zi));outer=B(.5L)*(B(1)+mf::tanh_(zo));}return B(T(p.parameters[6]))+B(T(p.parameters[9]))/(radius+B(T(p.parameters[7])))*inner*outer;}
template<class T> static std::array<mf::B<T>,NMOMENT> physical_moment(const curved::Packet&p,const mf::Point<T>&v,mf::B<T>rho,mf::B<T>x,mf::B<T>y,mf::B<T>w){using B=mf::B<T>;std::array<B,NMOMENT> z;B dm=rho*w/v.J,vx=v.velocity[0],vy=v.velocity[1],P=B(T(p.parameters[2]))*mf::power(v.J,T(-p.parameters[1]));z[MASS]=dm;z[PX]=dm*vx;z[PY]=dm*vy;z[ANGULAR]=dm*(x*vy-y*vx);z[KINETIC]=B(.5L)*dm*(vx*vx+vy*vy);z[THERMAL]=P*w/(B(T(p.parameters[1]))-B(1));z[VOLUME]=w;z[QX]=dm*x;z[QY]=dm*y;z[POLAR]=dm*(x*x+y*y);z[THERMAL_RATE]=-P*w*(v.grad_v[0]+v.grad_v[3]);z[POTENTIAL]=-dm/mf::root(x*x+y*y+B(T(p.parameters[3]))*B(T(p.parameters[3])));return z;}
struct Positive {uint64_t triangle,target,loop,boundary;Q x[2],X[2],weight,physical_radius[2],inverse_radius,weight_radius;R moment[NMOMENT],error[NMOMENT];};
#ifndef GFS_CURVED_TARGET_INTEGRAL_LIBRARY
int main(int argc,char**argv){int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);active_mpi=true;need(argc==6,"original packet sites guard new-output 225|137");size_t it=atoi(argv[5]);need(it==225||it==137,"same physical controls");auto p=curved::read(argv[1]);auto sites=curved_partition::read_sites(argv[2]);auto weights=read_weights(argv[3],sites);std::string dest=argv[4];const auto&r=p.record[it];Q anchor[2]={};curved_bounds::Tri tri;for(int k=0;k<2;k++){S center;for(int a=0;a<3;a++){center=center+S(Q(r.triangle.geometry.x[a][k]))/S(3);tri[a][k]=r.triangle.geometry.x[a][k];}anchor[k]=center.n;}auto map=tg::compile(r,anchor,p.parameters[3]);int own=-1;for(size_t j=0;j<sites.size();j++)if(sites[j].id==r.cell)own=j;need(own>=0,"source owner");auto bound=positive_source_bounds(r,tri,p.parameters[3]);auto possible=source_candidates(r,bound,sites,weights,own);auto gauss=ti::gauss16();auto started=std::chrono::steady_clock::now();mf::B<R> total[24][NMOMENT];S reference[24][NMOMENT];std::vector<Positive> saved;
    uint64_t oracle_excess=0,inside_points=0,empty_targets=0,nloops=0,nsegments=0;std::ofstream domains(dest+"/physical_domains.csv"),boundaries(dest+"/physical_boundaries.csv");domains<<"target,empty,loops,boundaries,nodes,root_evaluations,whole_domain_covered\n";boundaries<<"target,loop,boundary,source_edge,first,last,lo,hi,min_star_J,anchor_x,anchor_y\n";
    for(int target:possible)if(target!=own){auto domain=td::build(map,r,sites,weights,target);domains<<sites[target].id<<','<<domain.empty<<','<<domain.loop.size()<<','<<domain.boundary.size()<<','<<domain.node.size()<<','<<domain.root_evaluations<<",true\n";empty_targets+=domain.empty;nloops+=domain.loop.size();nsegments+=domain.boundary.size();for(size_t il=0;il<domain.loop.size();il++){const auto&loop=domain.loop[il];for(int ib:loop.boundary){const auto&boundary=domain.boundary[ib];boundaries<<sites[target].id<<','<<il<<','<<ib<<','<<boundary.edge<<','<<boundary.first<<','<<boundary.last<<','<<qs(boundary.lo.n)<<','<<qs(boundary.hi.n)<<','<<qs(loop.min_star_J)<<','<<qs(loop.anchor[0])<<','<<qs(loop.anchor[1])<<'\n';
                // Four fixed angular sectors, same positive16x16 rules.
                // These are physical fan coordinates, not polar-ray roots.
                for(int sector=0;sector<4;sector++)for(int iu=0;iu<16;iu++)for(int iv=0;iv<16;iv++){S u=(S(sector)+gauss.x[iu])/S(4),s=gauss.x[iv];auto curve=td::curve(domain,map,r,boundary,u);S delta[2]={curve.x[0]-S(loop.anchor[0]),curve.x[1]-S(loop.anchor[1])},J=td::cross(delta,curve.d);need(ti::lower(J)>0,"positive physical fan point");S x[2]={S(loop.anchor[0])+s*delta[0],S(loop.anchor[1])+s*delta[1]},w=s*J*gauss.w[iu]*gauss.w[iv]/S(4);need(ti::lower(w)>0,"all physical weights positive");auto inverse=tg::inverse(map,r,x[0],x[1]);need(inverse.inside,"physical positive quadrature lies strictly inside original source");inside_points++;auto native=tg::evaluate<R>(map,inverse.X,inverse.Y);auto oracle=mf::original_at(r,inverse.X,inverse.Y,p.parameters[3]);auto nrho=profile(p,ti::cast(inverse.X),ti::cast(inverse.Y),true);auto qrho=profile(p,inverse.X,inverse.Y,false);auto nn=physical_moment(p,native,nrho,ti::cast(x[0]),ti::cast(x[1]),ti::cast(w));auto oo=physical_moment(p,oracle,qrho,x[0],x[1],w);Positive point={};point.triangle=it;point.target=sites[target].id;point.loop=il;point.boundary=ib;for(int k=0;k<2;k++){point.x[k]=x[k].n;point.X[k]=k?inverse.Y.n:inverse.X.n;point.physical_radius[k]=x[k].e;}point.weight=w.n;point.weight_radius=w.e;point.inverse_radius=inverse.radius;for(int k=0;k<NMOMENT;k++){if(fabsq(Q(nn[k].n)-oo[k].n)>mf::FP<Q>::up(Q(nn[k].e)+oo[k].e))oracle_excess++;total[target][k]=total[target][k]+nn[k];reference[target][k]=reference[target][k]+oo[k];point.moment[k]=nn[k].n;point.error[k]=nn[k].e;}saved.push_back(point);}}}}
    domains.close();boundaries.close();need(oracle_excess==0,"original basis/profile within all native moment forward models");std::ofstream out(dest+"/physical_target_moments.csv");out<<std::setprecision(21)<<"source,target,moment,native,original_basis_same_rule,field_geometry_node_sum_bound,observed_same_rule_difference,analytic_remainder_complete,gluing_complete,source_baseline_complete\n";for(int target:possible)if(target!=own)for(int k=0;k<NMOMENT;k++)out<<r.cell<<','<<sites[target].id<<','<<moment_names[k]<<','<<total[target][k].n<<','<<qs(reference[target][k].n)<<','<<total[target][k].e<<','<<qs(fabsq(Q(total[target][k].n)-reference[target][k].n))<<",false,false,false\n";out.close();FILE*f=fopen((dest+"/physical_positive_points.bin").c_str(),"wb");need(f,"new physical-domain positive packet");uint64_t header[6]={0x47465447454e3031ULL,1,it,saved.size(),sizeof(Positive),16};need(fwrite(header,sizeof(header),1,f)==1&&fwrite(saved.data(),sizeof(Positive),saved.size(),f)==saved.size(),"new positive source/target packet complete");fclose(f);
    printf("{\"scope\":\"same original nonzero-residual225/137; physical source/target intersection, original-map inverse and native FMA/profile moment integration; no polar-ray call, refit, heat correction or time evolution\",\"triangle\":%zu,\"possible_receivers\":%zu,\"proved_empty_receivers\":%llu,\"positive_domain_loops\":%llu,\"oriented_boundary_segments\":%llu,\"positive_points\":%zu,\"points_inside_original_source\":%llu,\"oracle_excess\":%llu,\"positive_target_quadrature_complete\":true,\"analytic_remainder_complete\":false,\"gluing_and_source_baseline_complete\":false,\"full_cold_transfer_proved\":false,\"seconds\":%.17g}\n",it,possible.size()-1,(unsigned long long)empty_targets,(unsigned long long)nloops,(unsigned long long)nsegments,saved.size(),(unsigned long long)inside_points,(unsigned long long)oracle_excess,std::chrono::duration<double>(std::chrono::steady_clock::now()-started).count());active_mpi=false;MPI_Finalize();return 0;
}
#endif
